# Call sites of the E147 accelerometer and PER_ROTATE notes, plus the EXIF map table.
# Read-only. Do not edit this file after it has run.
import hashlib
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
n = len(img)
TARGETS = {
    0x60077D18: 'rotate-init',
    0x60077DE1: 'rotate-get',
    0x60077E0A: 'rotate-task',
    0x6006F28E: 'reg-read',
    0x6006A791: 'probe',
    0x6006A8CA: 'completion',
    0x6006A9C1: 'copy',
    0x6006A660: 'acc-main',
    0x60070436: 'acc-init',  # 0x50049416
    0x6006A936: 'enable-set',  # placeholder, replaced below
}


def s32(o):
    v = int.from_bytes(img[o:o + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16(o):
    v = int.from_bytes(img[o:o + 2], 'little')
    return v - 0x10000 if v & 0x8000 else v


# corrected cached addresses from native notes
native = {
    'acc-init': 0x50049416,
    'acc-device': 0x50049B44,
    'acc-main': 0x50049640,
    'probe': 0x50049771,
    'sampler': 0x50049700,
    'pin-cb': 0x50049849,
    'reg-read': 0x5004E26E,
    'completion': 0x500498AA,
    'correct': 0x50049B74,
    'convert': 0x50049F77,
    'remap': 0x5005CB7C,
    'copy': 0x500499A1,
    'slope-init': 0x5005C730,
    'slope-task': 0x5005C79B,
    'rotate-init': 0x50056CF8,
    'rotate-get': 0x50056DC1,
    'rotate-task': 0x50056DEA,
    'enable-set': 0x50049616,
    'enable-clr': 0x50049621,
}
targets = {BASE + (addr - 0x50000000): name for name, addr in native.items()}
lines = [f'target {name} cached {addr:#x}' for addr, name in sorted(targets.items())]
hits = {name: [] for name in targets.values()}
i = 0
while i < n - 6:
    op = img[i]
    pc = BASE + i
    found = None
    if op == 0xDD and i + 7 <= n:
        found = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCD and i + 5 <= n:
        found = (pc + s16(i + 1)) & 0xFFFFFFFF
    elif op == 0xDC and i + 5 <= n:
        found = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCC and i + 3 <= n:
        found = (pc + s16(i + 1)) & 0xFFFFFFFF
    elif op == 0xFC and img[i + 1] == 0xFF and i + 6 <= n:
        found = (pc + s32(i + 2)) & 0xFFFFFFFF
    elif op == 0xFA and img[i + 1] == 0xFF and i + 4 <= n:
        found = (pc + s16(i + 2)) & 0xFFFFFFFF
    name = targets.get(found)
    if name and len(hits[name]) < 40:
        hits[name].append(pc)
    i += 1
for name, pcs in hits.items():
    shown = ' '.join(f'{p:08x}' for p in pcs)
    lines.append(f'{name} calls {len(pcs)} {shown}')

needle = bytes([0x11, 0x00, 0x01, 0x00, 0x06, 0x00, 0x03, 0x00, 0x08, 0x00])
lines.append('exif halfword table 11,1,6,3,8:')
start = 0
while True:
    j = img.find(needle, start)
    if j < 0:
        break
    lines.append(f'  {BASE + j:08x}')
    start = j + 1

# event immediate 0x04020310
ev = (0x04020310).to_bytes(4, 'little')
lines.append('immediate 0x04020310:')
start = 0
count = 0
while count < 20:
    j = img.find(ev, start)
    if j < 0:
        break
    lines.append(f'  {BASE + j:08x}')
    count += 1
    start = j + 1
lines.append(f'event hits shown {count}')

text = '\n'.join(lines) + '\n'
Path('work/out/scan-calls-s2.txt').write_text(text, encoding='utf-8')
print(text)
print('sha', hashlib.sha256(img).hexdigest())
